import pickle

def score_job(job):
    return {'course':job['course'],'total':sum(job['points'])}

trusted_job={'course':'PY-102','points':(4,6)}
received=pickle.loads(pickle.dumps(trusted_job))
assert received==trusted_job

lab.testCode:
assert score_job(received)=={'course':'PY-102','total':10}
assert trusted_job=={'course':'PY-102','points':(4,6)}
assert score_job({'course':'PY-103','points':(1,2,3)})=={'course':'PY-103','total':6}
print('PASS: trusted local payload round-trip')
